import string as _string

import pytest
from hypothesis import given
import hypothesis.strategies as st

from solution import prime_length


def _is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    r = int(n ** 0.5)
    for d in range(3, r + 1, 2):
        if n % d == 0:
            return False
    return True


def test_examples_from_spec():
    assert prime_length('Hello') == True
    assert prime_length('abcdcba') == True
    assert prime_length('kittens') == True
    assert prime_length('orange') == False


def test_small_boundary_lengths():
    assert prime_length('') is False  # length 0, not prime
    assert prime_length('a') is False  # length 1, not prime
    assert prime_length('ab') is True  # length 2, prime
    assert prime_length('abc') is True  # length 3, prime
    assert prime_length('abcd') is False  # length 4, composite
    assert prime_length('abcde') is True  # length 5, prime
    assert prime_length('abcdef') is False  # length 6, composite


def test_large_primes_beyond_hardcoded_list():
    # Primes larger than 31 must still return True.
    for p in [37, 41, 43, 47, 53, 59, 61, 71, 97, 101, 127]:
        s = 'a' * p
        assert prime_length(s) is True, f"length {p} is prime"


def test_large_composites_return_false():
    for n in [32, 33, 35, 36, 49, 50, 100, 121, 150, 200]:
        assert not _is_prime(n)
        assert prime_length('a' * n) is False, f"length {n} is composite"


def test_matches_reference_model():
    @given(st.text(alphabet='abcXYZ ', max_size=150))
    def inner(s):
        assert type(s) == str
        expected = _is_prime(len(s))
        got = prime_length(s)
        assert got is expected
    inner()


def test_matches_reference_model_all_lengths_up_to_200():
    @given(st.integers(min_value=0, max_value=200))
    def inner(n):
        s = 'x' * n
        assert prime_length(s) is _is_prime(n)
    inner()


def test_same_length_same_result_metamorphic():
    @given(
        st.text(alphabet='ab', max_size=120),
        st.text(alphabet='xyz!@#', max_size=120),
    )
    def inner(s1, s2):
        # Pad/trim s2 to same length as s1 with different content where possible.
        n = len(s1)
        s2_fixed = (s2 + 'q' * n)[:n]
        assert len(s2_fixed) == n
        assert prime_length(s1) == prime_length(s2_fixed)
    inner()


def test_length_one_more_than_prime_reference():
    # Metamorphic: result must follow primality of len, not fixed table.
    @given(st.integers(min_value=0, max_value=150))
    def inner(n):
        s = 'a' * n
        s2 = s + 'b'
        assert prime_length(s) is _is_prime(n)
        assert prime_length(s2) is _is_prime(n + 1)
    inner()
